-- Prepared only. Not executed against HostGator or any MySQL server.
CREATE TABLE IF NOT EXISTS forum_profiles(user_id VARCHAR(32) PRIMARY KEY,display_name VARCHAR(60) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS forum_posts(id VARCHAR(32) PRIMARY KEY,author_id VARCHAR(32) NOT NULL,request_id CHAR(32) NOT NULL,request_hash CHAR(64) NOT NULL,space VARCHAR(12) NOT NULL,category VARCHAR(30) NOT NULL,title VARCHAR(160) NOT NULL,body TEXT NOT NULL,links_json TEXT NOT NULL,tags_json TEXT NOT NULL,module_id VARCHAR(80) NOT NULL,practice_id VARCHAR(80) NOT NULL,revision BIGINT NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,activity_at BIGINT NOT NULL,deleted_at BIGINT NULL,UNIQUE(author_id,request_id),FOREIGN KEY(author_id) REFERENCES users(id),INDEX forum_space_activity(space,deleted_at,activity_at,id),INDEX forum_module_activity(module_id,deleted_at,activity_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS forum_comments(id VARCHAR(32) PRIMARY KEY,post_id VARCHAR(32) NOT NULL,author_id VARCHAR(32) NOT NULL,request_id CHAR(32) NOT NULL,request_hash CHAR(64) NOT NULL,body TEXT NOT NULL,links_json TEXT NOT NULL,created_at BIGINT NOT NULL,deleted_at BIGINT NULL,UNIQUE(author_id,request_id),FOREIGN KEY(post_id) REFERENCES forum_posts(id),FOREIGN KEY(author_id) REFERENCES users(id),INDEX forum_post_comments(post_id,created_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS forum_avatars(user_id VARCHAR(32) PRIMARY KEY,jpeg_base64 MEDIUMTEXT NOT NULL,version CHAR(64) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS forum_acceptances(user_id VARCHAR(32) NOT NULL,kind VARCHAR(20) NOT NULL,version VARCHAR(32) NOT NULL,document_hash CHAR(64) NOT NULL,document_json TEXT NOT NULL,accepted_at BIGINT NOT NULL,adult_declared TINYINT NOT NULL,PRIMARY KEY(user_id,kind,version,document_hash),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS forum_reports(id CHAR(32) PRIMARY KEY,post_id VARCHAR(32) NOT NULL,reporter_id VARCHAR(32) NOT NULL,reason VARCHAR(20) NOT NULL,detail TEXT NOT NULL,created_at BIGINT NOT NULL,status VARCHAR(20) NOT NULL,UNIQUE(post_id,reporter_id),FOREIGN KEY(post_id) REFERENCES forum_posts(id),FOREIGN KEY(reporter_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Moderation/images prepared only; requires MySQL validation before deployment.
CREATE TABLE IF NOT EXISTS forum_moderators(user_id VARCHAR(32) PRIMARY KEY,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS forum_hidden(post_id VARCHAR(32) PRIMARY KEY,moderator_id VARCHAR(32) NOT NULL,reason TEXT NOT NULL,created_at BIGINT NOT NULL,FOREIGN KEY(post_id) REFERENCES forum_posts(id),FOREIGN KEY(moderator_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS forum_blocks(user_id VARCHAR(32) PRIMARY KEY,active BIGINT NOT NULL,reason TEXT NOT NULL,moderator_id VARCHAR(32) NOT NULL,updated_at BIGINT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(moderator_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS forum_moderation_actions(id VARCHAR(32) PRIMARY KEY,moderator_id VARCHAR(32) NOT NULL,request_id CHAR(32) NOT NULL,request_hash CHAR(64) NOT NULL,action VARCHAR(20) NOT NULL,target_id VARCHAR(80) NOT NULL,reason TEXT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(moderator_id,request_id),FOREIGN KEY(moderator_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS forum_report_snapshots(report_id VARCHAR(32) PRIMARY KEY,snapshot_json TEXT NOT NULL,FOREIGN KEY(report_id) REFERENCES forum_reports(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS forum_images(id VARCHAR(32) PRIMARY KEY,owner_id VARCHAR(32) NOT NULL,request_id CHAR(32) NOT NULL,request_hash CHAR(64) NOT NULL,post_id VARCHAR(32),jpeg_base64 MEDIUMTEXT NOT NULL,version CHAR(64) NOT NULL,width BIGINT NOT NULL,height BIGINT NOT NULL,created_at BIGINT NOT NULL,position BIGINT NOT NULL,UNIQUE(owner_id,request_id),FOREIGN KEY(owner_id) REFERENCES users(id),FOREIGN KEY(post_id) REFERENCES forum_posts(id),INDEX forum_images_post(post_id,position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
